function makeCounter(start) {
  let count = start;            // private: nothing outside can touch it
  return {
    increment: () => ++count,
    reset: () => (count = start),
  };
}

const a = makeCounter(0);
const b = makeCounter(100);
a.increment(); // 1
a.increment(); // 2
b.increment(); // 101 -- b has its own count

const makeMultiplier = (factor) => (n) => n * factor;
const triple = makeMultiplier(3);
triple(5); // 15

function once(fn) {
  let called = false;
  let result;
  return (...args) => {
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}
